<template>
  <div class="commercial-page">
    <section class="commercial-hero security-hero"><div><span class="eyebrow">ENTERPRISE SECURITY</span><h2>身份与模型策略</h2><p>MFA 面向当前账号；SSO 和模型供应商策略仅由企业所有者维护。</p></div><div class="security-badge"><el-icon><Lock /></el-icon><div><strong>{{app.currentMember?.owner?'企业所有者':'企业成员'}}</strong><small>敏感值不会写入浏览器存储</small></div></div></section>
    <section class="security-grid">
      <article class="commercial-card security-card"><header><div><span class="eyebrow">PERSONAL MFA</span><h3>多因素认证</h3></div><el-tag type="success" effect="plain">TOTP</el-tag></header><p>为当前账号绑定验证器。密钥只在本次注册弹窗中短暂显示，关闭后立即清除。</p><div class="security-actions"><el-button type="primary" @click="startMfa">注册/重新绑定 MFA</el-button><el-button type="danger" plain @click="disableOpen=true">停用 MFA</el-button></div></article>
      <article class="commercial-card security-card" :class="{locked:!app.currentMember?.owner}"><header><div><span class="eyebrow">ENTERPRISE SSO</span><h3>OIDC 单点登录</h3></div><el-tag :type="oidcForm.enabled?'success':'info'">{{oidcForm.enabled?'已启用':'未启用'}}</el-tag></header><p>配置企业身份提供商。客户端密钥字段只保存服务端密钥引用，不回显真实密钥。</p><div v-if="!app.currentMember?.owner" class="role-lock"><el-icon><Lock /></el-icon><span>仅企业所有者可查看和修改 SSO 策略。</span></div><el-button v-else type="primary" plain @click="oidcOpen=true">配置 OIDC</el-button></article>
      <article class="commercial-card security-card" :class="{locked:!app.currentMember?.owner}"><header><div><span class="eyebrow">MODEL GOVERNANCE</span><h3>模型供应商策略</h3></div><el-tag effect="plain">数据分级</el-tag></header><p>限定供应商、区域、出境策略和外部模型开关；不在页面采集供应商 API Key。</p><div v-if="!app.currentMember?.owner" class="role-lock"><el-icon><Lock /></el-icon><span>仅企业所有者可调整模型供应商策略。</span></div><el-button v-else type="primary" plain @click="modelOpen=true">配置模型策略</el-button></article>
    </section>
    <CommonDialog v-model="mfaOpen" title="绑定多因素认证" width="560px" @closed="clearMfa"><template v-if="enrollment"><el-alert title="请将密钥录入可信验证器，然后输入一次动态验证码确认。" type="warning" :closable="false" show-icon /><el-form label-position="top" style="margin-top:16px"><el-form-item label="一次性密钥"><el-input :model-value="enrollment.secret" type="password" show-password readonly /></el-form-item><el-form-item label="OTPAuth URI"><el-input :model-value="enrollment.otpauthUri" type="password" show-password readonly /></el-form-item><el-form-item label="6 位动态验证码"><el-input v-model.trim="mfaCode" maxlength="6" inputmode="numeric" autocomplete="one-time-code" /></el-form-item></el-form></template><UnifiedState v-else state="loading" description="正在创建临时 MFA 因子。" /><template #footer><el-button @click="mfaOpen=false">取消</el-button><el-button type="primary" :loading="confirmingMfa" :disabled="mfaCode.length!==6" @click="confirmMfa">确认绑定</el-button></template></CommonDialog>
    <CommonDialog v-model="disableOpen" title="停用 MFA" width="460px"><el-alert title="停用后账号将只依赖主登录凭据，请谨慎操作。" type="warning" :closable="false" /><el-form label-position="top" style="margin-top:16px"><el-form-item label="当前动态验证码"><el-input v-model.trim="disableCode" maxlength="6" type="password" show-password /></el-form-item></el-form><template #footer><el-button @click="disableOpen=false">取消</el-button><el-button type="danger" :loading="disablingMfa" :disabled="disableCode.length!==6" @click="disableMfa">确认停用</el-button></template></CommonDialog>
    <CommonDialog v-model="oidcOpen" title="企业 OIDC 单点登录" width="720px"><el-form label-position="top"><div class="commercial-form-grid"><el-form-item label="Issuer"><el-input v-model.trim="oidcForm.issuer" /></el-form-item><el-form-item label="Client ID"><el-input v-model.trim="oidcForm.clientId" /></el-form-item><el-form-item label="客户端密钥引用"><el-input v-model.trim="oidcForm.clientSecretRef" placeholder="例如 OIDC_SECRET_PROD" /></el-form-item><el-form-item label="允许邮箱域"><el-input v-model.trim="oidcForm.emailDomain" placeholder="example.com" /></el-form-item><el-form-item label="授权端点"><el-input v-model.trim="oidcForm.authorizationEndpoint" /></el-form-item><el-form-item label="Token 端点"><el-input v-model.trim="oidcForm.tokenEndpoint" /></el-form-item><el-form-item label="JWKS URI"><el-input v-model.trim="oidcForm.jwksUri" /></el-form-item><el-form-item label="启用"><el-switch v-model="oidcForm.enabled" /></el-form-item></div></el-form><el-alert title="所有端点必须使用 HTTPS 且与 Issuer 同源；真实客户端密钥由服务端密钥存储解析。" type="info" :closable="false" /><template #footer><el-button @click="oidcOpen=false">取消</el-button><el-button type="primary" :loading="savingOidc" @click="saveOidc">保存策略</el-button></template></CommonDialog>
    <CommonDialog v-model="modelOpen" title="模型供应商策略" width="620px"><el-form label-position="top"><div class="commercial-form-grid"><el-form-item label="供应商编码"><el-input v-model.trim="modelForm.providerCode" /></el-form-item><el-form-item label="模型名称"><el-input v-model.trim="modelForm.modelName" /></el-form-item><el-form-item label="处理区域"><el-select v-model="modelForm.region"><el-option label="中国大陆" value="cn"/><el-option label="新加坡" value="sg"/><el-option label="欧盟" value="eu"/></el-select></el-form-item><el-form-item label="数据策略"><el-select v-model="modelForm.dataPolicy"><el-option label="仅聚合数据" value="AGGREGATE_ONLY"/><el-option label="允许明细数据" value="DETAIL_ALLOWED"/></el-select></el-form-item><el-form-item label="外部模型"><el-switch v-model="modelForm.externalEnabled" active-text="允许" inactive-text="禁止" /></el-form-item></div><h4>每百万 Token 价格（最小货币单位）</h4><div class="commercial-form-grid"><el-form-item label="输入"><el-input-number v-model="modelForm.prices.promptPerMillion" :min="0" style="width:100%" /></el-form-item><el-form-item label="输出"><el-input-number v-model="modelForm.prices.completionPerMillion" :min="0" style="width:100%" /></el-form-item></div></el-form><template #footer><el-button @click="modelOpen=false">取消</el-button><el-button type="primary" :loading="savingModel" @click="saveModel">保存策略</el-button></template></CommonDialog>
  </div>
</template>

<script setup lang="ts">
import { ref } from 'vue'; import { Lock } from '@element-plus/icons-vue'; import { ElMessage } from 'element-plus'; import CommonDialog from '../components/common/CommonDialog.vue'; import UnifiedState from '../components/common/UnifiedState.vue'; import { commercialApi } from '../api/runtime'; import type { MfaEnrollment, OidcConfig } from '../commercial/types'; import { useAppStore } from '../stores/app'
const app=useAppStore(); const mfaOpen=ref(false); const enrollment=ref<MfaEnrollment>(); const mfaCode=ref(''); const confirmingMfa=ref(false); const disableOpen=ref(false); const disableCode=ref(''); const disablingMfa=ref(false); const oidcOpen=ref(false); const savingOidc=ref(false); const modelOpen=ref(false); const savingModel=ref(false)
const oidcForm=ref<OidcConfig>({issuer:'',clientId:'',clientSecretRef:'',authorizationEndpoint:'',tokenEndpoint:'',jwksUri:'',emailDomain:'',enabled:false}); const modelForm=ref({providerCode:'',modelName:'',region:'cn',dataPolicy:'AGGREGATE_ONLY',externalEnabled:false,prices:{promptPerMillion:0,completionPerMillion:0}})
async function loadOwnerSettings(){if(!app.currentMember?.owner)return;try{oidcForm.value=await commercialApi.oidc()}catch{/* Not configured yet. */}}
async function startMfa(){mfaOpen.value=true;mfaCode.value='';enrollment.value=undefined;try{enrollment.value=await commercialApi.enrollMfa()}catch(e){mfaOpen.value=false;ElMessage.error(e instanceof Error?e.message:'MFA 注册失败')}} function clearMfa(){enrollment.value=undefined;mfaCode.value=''}
async function confirmMfa(){confirmingMfa.value=true;try{await commercialApi.confirmMfa(mfaCode.value);ElMessage.success('MFA 已由服务端确认启用');mfaOpen.value=false}finally{confirmingMfa.value=false}}
async function disableMfa(){disablingMfa.value=true;try{await commercialApi.disableMfa(disableCode.value);disableCode.value='';disableOpen.value=false;ElMessage.success('MFA 已停用')}finally{disablingMfa.value=false}}
async function saveOidc(){if(!app.currentMember?.owner)return;savingOidc.value=true;try{oidcForm.value=await commercialApi.configureOidc(oidcForm.value);oidcOpen.value=false;ElMessage.success('OIDC 策略已保存')}finally{savingOidc.value=false}}
async function saveModel(){if(!app.currentMember?.owner)return;savingModel.value=true;try{await commercialApi.configureModel(modelForm.value);modelOpen.value=false;ElMessage.success('模型供应商策略已保存')}finally{savingModel.value=false}}
void loadOwnerSettings()
</script>
